import*as THREE from'three';import{Component,Port,materials}from'../../core/index.js';import{addCadParts}from'../../modeling/cad.js';import{mesh,slab,screw,FACE,portQuaternion}from'../../modeling/parts.js';import{spec}from'./dimensions.js';import data from'./geometry-data.js';import{addStickers}from'./stickers.js';
const tau=Math.PI*2;const hole=(s,x,y,r)=>{const p=new THREE.Path();p.absarc(x,y,r,0,tau,false);s.holes.push(p);};
function solid(p,s,depth,pos,mat,name){return mesh(p,new THREE.ExtrudeGeometry(s,{depth,bevelEnabled:false,curveSegments:64}),mat,pos,name);}
function annulus(p,outer,inner,depth,pos,mat,name){const s=new THREE.Shape();s.absarc(0,0,outer,0,tau,false);hole(s,0,0,inner);return solid(p,s,depth,pos,mat,name);}
function electronics(host){
 const s=new THREE.Shape();s.moveTo(-10.2,27);s.lineTo(-3.5,27);s.lineTo(-3.5,23.4);s.lineTo(3.5,23.4);s.lineTo(3.5,27);s.lineTo(10.2,27);s.lineTo(10.2,-16.6);s.lineTo(8,-16.6);s.absarc(8,-20,3.4,Math.PI/2,Math.PI*1.5,false);s.lineTo(10.2,-23.4);s.lineTo(10.2,-29);s.lineTo(5.7,-29);s.lineTo(5.7,-24.8);s.lineTo(-5.7,-24.8);s.lineTo(-5.7,-29);s.lineTo(-10.2,-29);s.lineTo(-10.2,-23.4);s.lineTo(-8,-23.4);s.absarc(-8,-20,3.4,Math.PI*1.5,Math.PI*2.5,false);s.lineTo(-10.2,-16.6);s.closePath();hole(s,0,-20,1.8);
 const pcb=solid(host.body,s,.8,[0,0,-1.5],materials.plastic(0x264a36,{roughness:.91}),'DDS fixed PCB with three genuine mounting clearances and Grove relief');pcb.userData={role:'physical-pcb',inferred:true};
 const dark=materials.plastic(0x1c221f,{roughness:.85}),metal=materials.metal(0xb8b6a5,{roughness:.43}),ceramic=materials.plastic(0xab9c78,{roughness:.9});
 const stm=slab(host.body,5,5,.9,.1,[0,-4,-.7],dark,[],.015);stm.name='DDS IC1 STM32F031G4x fixed controller package';for(const sign of[-1,1])for(let i=0;i<7;i++){mesh(host.body,new THREE.BoxGeometry(.42,.24,.16),metal,[sign*2.6,-4+(i-3)*.6,-.62],'DDS STM32 physical terminal');mesh(host.body,new THREE.BoxGeometry(.24,.42,.16),metal,[(i-3)*.6,-4+sign*2.6,-.62],'DDS STM32 physical terminal');}
 const dds=slab(host.body,3,3,1,.1,[0,7,-.7],dark,[],.015);dds.name='DDS IC2 AD9833 fixed ten-lead package';for(const sign of[-1,1])for(let i=0;i<5;i++)mesh(host.body,new THREE.BoxGeometry(.8,.28,.17),metal,[sign*1.85,7+(i-2)*.5,-.45],'DDS AD9833 physical lead');
 const opa=slab(host.body,2.9,1.6,1.05,.12,[0,17,-.7],dark,[],.015);opa.name='DDS IC3 OPA365 fixed analog buffer package';const regulator=slab(host.body,2.9,1.6,1,.12,[5.6,-10,-.7],dark,[],.015);regulator.name='DDS IC4 SPX3819 fixed regulator package';for(const[x,y]of[[0,17],[5.6,-10]])for(const side of[-1,1])for(let i=0;i<(side===1?2:3);i++)mesh(host.body,new THREE.BoxGeometry(.25,.75,.15),metal,[x+(i-(side===1?.5:1))*.7,y+side*1.0,-.45],'DDS fixed SOT package lead');
 const crystal=slab(host.body,3.2,2.5,.8,.25,[-5.9,-9,-.7],metal,[],.025);crystal.name='DDS X1 fixed25M clock can';const rp=slab(host.body,3.2,1.7,.7,.06,[5.6,5,-.7],dark,[],.015);rp.name='DDS RP1 fixed resistor array';for(let i=0;i<4;i++)for(const side of[-1,1])mesh(host.body,new THREE.BoxGeometry(.25,.45,.15),metal,[4.55+i*.7,5+side*.9,-.4],'DDS RP1 physical termination');
 for(const[x,y]of[[-6,17],[5,18],[-5,11],[5,11],[-5,3],[0,1],[6,-2],[-6,-3],[-2,-11],[1,-11],[-6,-14],[5,-14],[0,22]]){mesh(host.body,new THREE.BoxGeometry(1.4,.8,.5),ceramic,[x,y,-.45],'DDS fixed physical passive package');for(const dx of[-.58,.58])mesh(host.body,new THREE.BoxGeometry(.28,.8,.52),metal,[x+dx,y,-.45],'DDS passive solder termination');}
 for(const[x,y]of[[-6,-10],[5,-12]]){mesh(host.body,new THREE.BoxGeometry(2,3.4,1.7),materials.plastic(0x8a7451,{roughness:.8}),[x,y,-.7],'DDS E1 E2 physical decoupling capacitor envelope');}
 for(let i=0;i<4;i++)mesh(host.body,new THREE.CylinderGeometry(.48,.48,.08,24).rotateX(Math.PI/2),materials.metal(0xc6ad56),[-4.2+i*1.4,-15,-.66],'DDS H1 concealed SWD pad');
 return{pcb,stm,dds,opa,regulator,crystal,rp};
}
function sma(host){
 const g=new THREE.Group();g.name='DDS true SMA female connector';g.position.fromArray(spec.sma.position);g.quaternion.copy(FACE.top);host.body.add(g);const gold=materials.metal(0xd1b85c,{roughness:.36}),white=materials.plastic(0xdcd9ba,{roughness:.75}),dark=materials.plastic(0x252b22,{roughness:.8});
 const barrel=annulus(g,2.78,2.1,10.3,[0,0,-10.3],gold,'DDS SMA continuous annular female outer barrel');
 const lip=annulus(g,2.78,2.1,.45,[0,0,-.45],gold,'DDS SMA open annular mating lip');
 class ThreadCurve extends THREE.Curve{getPoint(t,target=new THREE.Vector3()){const a=t*tau*9;return target.set(Math.cos(a)*2.94,Math.sin(a)*2.94,-7.2+t*6.3);}}
 const thread=mesh(g,new THREE.TubeGeometry(new ThreadCurve(),648,.16,8,false),gold,[0,0,0],'DDS SMA real continuous helical external thread');
 const hex=new THREE.Shape();for(let i=0;i<6;i++){const a=tau*i/6+Math.PI/6;const x=Math.cos(a)*3.13,y=Math.sin(a)*3.13;i?hex.lineTo(x,y):hex.moveTo(x,y);}hex.closePath();hole(hex,0,0,1.05);const nut=solid(g,hex,4,[0,0,-13.4],gold,'DDS SMA retained internal hex body visible through both native windows');
 const dielectric=annulus(g,2.095,.6,4.35,[0,0,-4.55],white,'DDS SMA recessed PTFE insulator with genuine centre bore');
 const contact=annulus(g,.58,.25,4,[0,0,-4.4],gold,'DDS SMA female hollow recessed centre contact sleeve');
 const stop=mesh(g,new THREE.CylinderGeometry(.25,.25,.12,32).rotateX(Math.PI/2),gold,[0,0,-4.56],'DDS SMA recessed centre contact blind end');
 const shoulder=annulus(g,1.04,.55,1.2,[0,0,-14.4],white,'DDS SMA rear feed-through dielectric');const rearPin=mesh(g,new THREE.CylinderGeometry(.24,.24,1.6,24).rotateX(Math.PI/2),gold,[0,0,-14.4],'DDS SMA rear centre terminal');
 const rear=annulus(g,1.45,.62,1.2,[0,0,-15],gold,'DDS SMA rear coax termination sleeve');
 const cablePath=new THREE.CatmullRomCurve3([new THREE.Vector3(0,24.3,0),new THREE.Vector3(0,22.7,.1),new THREE.Vector3(2,21,.3),new THREE.Vector3(4.9,21,-.1)]);const coax=mesh(host.body,new THREE.TubeGeometry(cablePath,36,.52,10,false),materials.plastic(0x252c27,{roughness:.86}),[0,0,0],'DDS concealed short coax backing from SMA to schematic IPEX output');
 const ipg=new THREE.Group();ipg.name='DDS COM1 fixed IPEX board output receptacle';ipg.position.set(4.9,21,-.65);host.body.add(ipg);const socket=annulus(ipg,1.2,.6,.6,[0,0,0],gold,'DDS COM1 physical annular IPEX outer socket');mesh(ipg,new THREE.CylinderGeometry(.25,.25,.5,20).rotateX(Math.PI/2),gold,[0,0,.25],'DDS COM1 IPEX centre terminal');
 const port=host.add(new Port({id:'sma',label:'SMA female · signal OUT',connector:'sma-female',position:spec.sma.position,quaternion:portQuaternion('top'),hitSize:[6.2,1,6.2],pins:[{n:1,name:'centre SMA_OUT'},{n:2,name:'outer AGND'}],meta:{role:'visual-connector',face:'top',signalRole:'analog-output',scope:'Female connector shape, external thread, real recessed centre socket, pose and matching connector type only; no waveform, frequency, phase, signal, power or electrical simulation'}}));return{group:g,barrel,lip,thread,nut,dielectric,contact,stop,shoulder,rearPin,rear,coax,ipex:ipg,socket,port};
}
function grove(host){const g=new THREE.Group();g.name='DDS open red HY2.0-4P socket';g.position.fromArray(spec.grove.position);g.quaternion.copy(FACE.bottom);host.body.add(g);const plastic=materials.plastic(spec.grove.color,{roughness:.66}),metal=materials.metal(0xc0b797,{roughness:.42}),box=(s,p,n,m=plastic)=>mesh(g,new THREE.BoxGeometry(...s),m,p,'DDS Grove '+n),depth=6.6;
 for(const sign of[-1,1]){box([.65,5.2,depth],[sign*4.675,0,-depth/2],'side wall');box([.7,.6,3.2],[sign*3.85,2.3,-4.9],'guide rail');box([.6,.45,1.2],[sign*3.65,2.375,-1.8],'latch shoulder');}box([8.7,.65,depth],[0,-2.275,-depth/2],'floor');box([8.7,4.55,.65],[0,.325,-depth+.325],'rear wall');box([4.8,.45,2.3],[0,2.375,-4.6],'locking bridge');const contacts=[];for(let i=0;i<4;i++){contacts.push(box([.42,.42,4.7],[(i-1.5)*2,.2,-3.7],`contact ${i+1}`,metal));box([.42,1.4,.42],[(i-1.5)*2,-2.7,-6],`solder tail ${i+1}`,metal);}
 const port=host.add(new Port({id:'grove',label:'PORT.A · I2C',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('bottom'),hitSize:[10,1,5.2],pins:[{n:1,name:'GND',color:'black'},{n:2,name:'5V',color:'red'},{n:3,name:'SDA',color:'yellow'},{n:4,name:'SCL',color:'white'}],meta:{role:'visual-connector',face:'bottom',scope:'Physical attachment, four contacts, pin labels and cable pose only; no I2C transaction, waveform, frequency, signal, supply or electrical behavior'}}));return{group:g,contacts,port};}
export function buildDds(host){const parts=addCadParts(host,data,{shell:materials.plastic(0x555956,{roughness:.85})}),board=electronics(host),output=sma(host),input=grove(host);const fixings=[];for(const[x,y]of[[0,-20],[-8.9,26],[8.9,26]]){const screwHead=screw(host.body,[x,y,-3.97],'back',1.35);fixings.push(screwHead);mesh(host.body,new THREE.CylinderGeometry(.6,.6,2,24).rotateX(Math.PI/2),materials.metal(0xa1a797),[x,y,-2.8],'DDS concealed fixed retaining screw shank');}const anchor=host.add(new Component({id:'sensor',label:'AD9833 appearance anchor',position:[0,7,.3],meta:{role:'visual-anchor',scope:'Passive fixed visual anchor only; no waveform, frequency, phase, sleep, DAC, signal, sensor-value, firmware or electrical commands'}}));host.ddsAssembly={parts,board,output,input,fixings,anchor};host.unitStickers=addStickers(host);}
